content.css:
@font-face {
  font-family: "Titillium Web";
  font-style: normal;
  font-weight: 400;
  font-display: block;
  src: url(data:font/woff2;base64,) format("woff2");
}
@font-face {
  font-family: "Titillium Web";
  font-style: normal;
  font-weight: 600;
  font-display: block;
  src: url(data:font/woff2;base64,) format("woff2");
}
@font-face {
  font-family: "Titillium Web";
  font-style: normal;
  font-weight: 700;
  font-display: block;
  src: url(data:font/woff2;base64,) format("woff2");
}
@font-face {
  font-family: "Titillium Web";
  font-style: normal;
  font-weight: 900;
  font-display: block;
  src: url(data:font/woff2;base64,) format("woff2");
}
@font-face {
  font-family: "Titillium Web";
  font-style: italic;
  font-weight: 700;
  font-display: block;
  src: url(data:font/woff2;base64,) format("woff2");
}
.pw-host {
  width: 100%;
  height: 100%;
}
.pw-root {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  user-select: none;
  color: #EAF0FF;
  font: 400 12px/1.3 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-variant-numeric: tabular-nums;
  background: radial-gradient(1100px 600px at 50% -18%, rgba(18, 32, 90, 0.85), transparent 70%), radial-gradient(700px 500px at 105% 105%, rgba(228, 0, 43, 0.12), transparent 60%), radial-gradient(600px 500px at -5% 100%, rgba(61, 123, 255, 0.1), transparent 60%), repeating-linear-gradient(45deg, rgba(255, 255, 255, 0.012) 0 2px, transparent 2px 6px), #040920;
}
.pw-root *,
.pw-root *::before,
.pw-root *::after {
  box-sizing: border-box;
}
.pw-root button,
.pw-root select,
.pw-root input {
  font-family: inherit;
}
.pw-root h1,
.pw-root h2 {
  margin: 0;
}
.num {
  font-variant-numeric: tabular-nums;
}
.dim {
  color: #5A6894;
}
.warn {
  color: #FF9F1C;
}
.purple {
  color: #B44DFF !important;
}
.r {
  text-align: right;
}
.c {
  text-align: center;
}
.pw-sub {
  font: 600 11px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #8B9BC6;
  text-transform: none;
  letter-spacing: 0;
}
.pw-label {
  font: 600 11px/1.2 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #8B9BC6;
}
.pw-empty {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: #5A6894;
  font: 600 12px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  pointer-events: none;
}
.pw-layer {
  position: absolute;
  inset: 0;
  display: block;
}
.pw-ax {
  font: 600 10px 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  fill: #8B9BC6;
}
.pw-ax--hi {
  fill: #fff;
  font-weight: 700;
}
.pw-header {
  flex: 0 0 auto;
  padding: 8px 12px 0;
}
.pw-header__bar {
  display: flex;
  align-items: center;
  gap: 16px;
  height: 58px;
  padding: 0 14px;
  background: linear-gradient(180deg, rgba(18, 32, 90, 0.7), rgba(11, 22, 64, 0.55));
  border: 1px solid rgba(110, 150, 255, 0.16);
  border-radius: 12px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 10px 30px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(10px);
}
.pw-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 0 0 auto;
  min-width: 200px;
}
.pw-brand__mark {
  display: flex;
  gap: 3px;
  transform: skewX(-18deg);
}
.pw-brand__mark i {
  display: block;
  width: 7px;
  height: 28px;
  border-radius: 1px;
  background: #E4002B;
  box-shadow: 0 0 12px rgba(228, 0, 43, 0.6);
}
.pw-brand__mark i + i {
  background: #FFC906;
  box-shadow: 0 0 12px rgba(255, 201, 6, 0.5);
}
.pw-brand__text {
  display: flex;
  flex-direction: column;
  line-height: 1;
}
.pw-brand__text b {
  font: italic 900 22px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.02em;
  color: #fff;
}
.pw-brand__text span {
  margin-top: 3px;
  font: 700 8.5px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.22em;
  color: #FFC906;
}
.pw-tabs {
  flex: 1 1 auto;
  display: flex;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  overflow: hidden;
}
.pw-tabs button {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-width: 86px;
  height: 50px;
  padding: 4px 10px;
  cursor: pointer;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 9px;
  color: #8B9BC6;
  font: 600 10.5px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.04em;
  transition: all 0.18s;
}
.pw-tabs button svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.pw-tabs button em {
  font: 600 8.5px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-style: normal;
  color: #FFC906;
  letter-spacing: 0.06em;
}
.pw-tabs button:hover {
  color: #EAF0FF;
  background: rgba(110, 150, 255, 0.07);
}
.pw-tabs button.is-on {
  color: #fff;
  border-color: rgba(110, 150, 255, 0.32);
  background: linear-gradient(180deg, rgba(61, 123, 255, 0.26), rgba(61, 123, 255, 0.06));
  box-shadow: inset 0 0 18px rgba(61, 123, 255, 0.25), 0 0 18px rgba(61, 123, 255, 0.18);
}
.pw-tabs button.is-on svg {
  stroke: #5B95FF;
  filter: drop-shadow(0 0 4px #5B95FF);
}
.pw-tabs button.is-on::after {
  content: "";
  position: absolute;
  left: 18%;
  right: 18%;
  bottom: -1px;
  height: 2px;
  border-radius: 2px;
  background: #E4002B;
  box-shadow: 0 0 10px #E4002B;
}
.pw-restroom {
  flex: 0 0 auto;
  cursor: pointer;
  height: 32px;
  padding: 0 12px;
  border-radius: 16px;
  background: rgba(255, 201, 6, 0.08);
  color: #FFC906;
  border: 1px solid rgba(255, 201, 6, 0.45);
  font: 700 11px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.02em;
  transition: all 0.18s;
}
.pw-restroom:hover {
  background: rgba(255, 201, 6, 0.16);
  box-shadow: 0 0 14px rgba(255, 201, 6, 0.25);
}
.pw-restroom.is-on {
  background: #FFC906;
  color: #0B1640;
}
.pw-titlerow {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 4px 2px;
}
.pw-titlerow h1 {
  font: 700 21px/1.1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.01em;
  color: #fff;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pw-titlerow h1 span {
  font-weight: 400;
  color: #EAF0FF;
}
.pw-pickers {
  display: flex;
  gap: 8px;
  flex: 0 0 auto;
}
.pw-pick {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.pw-pick span {
  font: 600 9.5px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #8B9BC6;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.pw-pick select {
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  min-width: 74px;
  height: 28px;
  padding: 0 26px 0 10px;
  color: #fff;
  font: 700 12px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  border-radius: 7px;
  border: 1px solid rgba(110, 150, 255, 0.32);
  background: rgba(11, 22, 64, 0.8) url("data:image/svg+xml;utf8,<svg xmlns=%27http://www.w3.org/2000/svg%27 width=%279%27 height=%276%27><path d=%27M0 0h9L4.5 6z%27 fill=%27%238B9BC6%27/></svg>") no-repeat right 9px center;
}
.pw-pick select:hover,
.pw-pick select:focus {
  outline: none;
  border-color: #5B95FF;
  box-shadow: 0 0 0 2px rgba(61, 123, 255, 0.25);
}
.pw-pick select option {
  background: #0B1640;
}
.pw-pick--wide select {
  min-width: 170px;
}
.pw-pick--a select {
  border-color: rgba(255, 43, 79, 0.6);
  box-shadow: inset 3px 0 0 #FF2B4F;
}
.pw-pick--b select {
  border-color: rgba(255, 201, 6, 0.55);
  box-shadow: inset 3px 0 0 #FFC906;
}
.pw-grid {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  gap: 10px;
  padding: 8px 12px;
}
.pw-card {
  position: relative;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 10px;
  border: 1px solid rgba(110, 150, 255, 0.16);
  background: linear-gradient(180deg, rgba(22, 38, 96, 0.55), rgba(8, 15, 44, 0.72));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), inset 0 0 30px rgba(61, 123, 255, 0.04), 0 14px 34px rgba(0, 0, 0, 0.38);
  backdrop-filter: blur(10px);
}
.pw-card__head {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 14px 6px;
}
.pw-card__head h2 {
  font: 700 13px/1.1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pw-card__head h2 .pw-sub {
  margin-left: 6px;
}
.pw-card__right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 0 1 auto;
  min-width: 0;
}
.pw-card__body {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.pw-card--flush {
  padding: 0;
}
.pw-legend {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font: 700 11px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #EAF0FF;
  white-space: nowrap;
}
.pw-legend i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}
.pw-legend b {
  color: #8B9BC6;
  font-weight: 600;
}
.pw-legend--delta b {
  color: #fff;
}
.pw-chips {
  display: inline-flex;
  padding: 2px;
  gap: 2px;
  border-radius: 8px;
  background: rgba(4, 9, 32, 0.6);
  border: 1px solid rgba(110, 150, 255, 0.16);
}
.pw-chips button {
  border: 0;
  background: transparent;
  color: #8B9BC6;
  font: 600 11px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  padding: 6px 10px;
  border-radius: 6px;
  cursor: pointer;
  white-space: nowrap;
}
.pw-chips button:hover {
  color: #fff;
}
.pw-chips button.is-on {
  color: #fff;
  background: linear-gradient(180deg, rgba(228, 0, 43, 0.85), rgba(228, 0, 43, 0.6));
  box-shadow: 0 0 12px rgba(228, 0, 43, 0.45);
}
.pw-chart {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  padding: 0 6px 4px;
}
.pw-card--track {
  background: radial-gradient(80% 70% at 45% 55%, rgba(30, 60, 160, 0.25), transparent 70%), linear-gradient(180deg, rgba(22, 38, 96, 0.5), rgba(8, 15, 44, 0.75));
}
.pw-trackmap {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  cursor: crosshair;
}
.pw-trackinfo {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  min-width: 150px;
  padding: 10px 12px;
  pointer-events: none;
  background: rgba(4, 9, 32, 0.72);
  border: 1px solid rgba(110, 150, 255, 0.32);
  border-radius: 8px;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.45);
}
.pw-trackinfo b {
  display: block;
  font: 700 13px/1.2 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #fff;
  margin-bottom: 6px;
}
.pw-trackinfo dl {
  display: grid;
  grid-template-columns: auto auto;
  gap: 2px 12px;
  margin: 0;
}
.pw-trackinfo dt {
  font: 600 11.5px/1.35 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #8B9BC6;
  text-transform: uppercase;
}
.pw-trackinfo dd {
  margin: 0;
  font: 700 12px/1.35 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #fff;
  text-align: right;
}
.pw-trackinfo__secs {
  margin-top: 6px !important;
  padding-top: 6px;
  border-top: 1px solid rgba(110, 150, 255, 0.16);
}
.pw-sectxt--purple {
  color: #B44DFF !important;
}
.pw-sectxt--green {
  color: #2BE38B !important;
}
.pw-sectxt--yellow {
  color: #FFC906 !important;
}
.pw-trackfoot {
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 10px;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.pw-trackfoot__meta {
  font: 600 11px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #8B9BC6;
}
.pw-trackmap.is-compact .pw-trackinfo {
  top: 8px;
  right: 8px;
  min-width: 128px;
  padding: 8px 10px;
}
.pw-trackmap.is-compact .pw-trackinfo b {
  font-size: 12px;
}
.pw-order {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 0 8px 6px;
}
.pw-order__head,
.pw-order__row {
  display: grid;
  grid-template-columns: 22px minmax(70px, 1.2fr) 66px minmax(54px, 1fr) 62px 74px;
  column-gap: 8px;
  align-items: center;
  padding: 0 6px;
}
.pw-order.is-timing .pw-order__head,
.pw-order.is-timing .pw-order__row {
  grid-template-columns: 22px minmax(70px, 1.1fr) 62px minmax(40px, 0.8fr) 70px 58px 66px 54px 62px;
}
.pw-order__head {
  height: 22px;
  font: 600 10.5px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #8B9BC6;
  border-bottom: 1px solid rgba(110, 150, 255, 0.16);
}
.pw-order__body {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
}
.pw-order__body::-webkit-scrollbar {
  width: 4px;
}
.pw-order__body::-webkit-scrollbar-thumb {
  background: rgba(110, 150, 255, 0.32);
  border-radius: 2px;
}
.pw-order__row {
  min-height: 25px;
  flex: 1 0 25px;
  max-height: 32px;
  cursor: pointer;
  border-radius: 6px;
  font: 600 12.5px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  transition: background 0.2s;
}
.pw-order__row:hover {
  background: rgba(110, 150, 255, 0.08);
}
.pw-order__row.is-focus {
  background: linear-gradient(90deg, rgba(255, 43, 79, 0.28), rgba(255, 43, 79, 0.04));
  box-shadow: inset 2px 0 0 #FF2B4F;
}
.pw-order__row.is-compare {
  background: linear-gradient(90deg, rgba(255, 201, 6, 0.2), rgba(255, 201, 6, 0.03));
  box-shadow: inset 2px 0 0 #FFC906;
}
.pw-order__row.is-out {
  opacity: 0.45;
}
.pw-order__body {
  display: flex;
  flex-direction: column;
}
.pw-order__pos {
  font-weight: 700;
  color: #8B9BC6;
}
.pw-order__drv {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}
.pw-order__drv i {
  width: 3px;
  height: 15px;
  border-radius: 2px;
  flex: 0 0 auto;
}
.pw-order__drv b {
  font-weight: 700;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pw-order__tyre {
  display: flex;
  align-items: center;
  gap: 6px;
}
.pw-order__tyre b {
  font-weight: 900;
  width: 10px;
}
.pw-order__tyre span {
  color: #8B9BC6;
  font-weight: 600;
  font-size: 11.5px;
}
.pw-order__life {
  height: 7px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}
.pw-order__life i {
  display: block;
  height: 100%;
  border-radius: 4px;
  box-shadow: 0 0 8px currentColor;
  transition: width 0.4s;
}
.pw-pill {
  font: 700 9px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-style: normal;
  padding: 2px 5px;
  border-radius: 3px;
  letter-spacing: 0.04em;
}
.pw-pill--pit {
  background: #3D7BFF;
  color: #fff;
}
.pw-pill--out {
  background: #E4002B;
  color: #fff;
}
.pw-secs {
  display: flex;
  gap: 3px;
  justify-content: center;
}
.pw-sec {
  width: 14px;
  height: 5px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.12);
  opacity: 0.5;
}
.pw-sec.is-live {
  opacity: 1;
}
.pw-sec--purple {
  background: #B44DFF;
}
.pw-sec--green {
  background: #2BE38B;
}
.pw-sec--yellow {
  background: #FFC906;
}
.pw-card--pit .pw-badges {
  padding: 0 14px 4px;
}
.pw-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 6px 14px;
}
.pw-badge {
  font: 700 10px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.06em;
  padding: 5px 8px;
  border-radius: 5px;
  border: 1px solid;
  text-transform: uppercase;
}
.pw-badge--ok {
  color: #2BE38B;
  border-color: rgba(43, 227, 139, 0.5);
  background: rgba(43, 227, 139, 0.1);
}
.pw-badge--warn {
  color: #FF9F1C;
  border-color: rgba(255, 159, 28, 0.55);
  background: rgba(255, 159, 28, 0.1);
}
.pw-badge--alert {
  color: #fff;
  border-color: #E4002B;
  background: rgba(228, 0, 43, 0.75);
  box-shadow: 0 0 14px rgba(228, 0, 43, 0.5);
  animation: pw-alert 1.1s ease-in-out infinite;
}
.pw-badge--info {
  color: #8B9BC6;
  border-color: rgba(110, 150, 255, 0.32);
}
@keyframes pw-alert {
  50% {
    box-shadow: 0 0 22px #E4002B;
  }
}
.pw-pitwin {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  gap: 10px;
  padding: 0 10px 8px 4px;
}
.pw-pitwin__chart {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
}
.pw-pitwin__side {
  flex: 0 0 132px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.pw-fuel div:first-of-type {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 3px;
}
.pw-fuel b {
  font: 700 16px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #fff;
}
.pw-fuel em {
  font: 700 12px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-style: normal;
  color: #8B9BC6;
}
.pw-bar {
  height: 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.08);
  margin-top: 5px;
  overflow: hidden;
}
.pw-bar i {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, #3D7BFF, #5B95FF);
  box-shadow: 0 0 10px #3D7BFF;
}
.pw-plans {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-height: 0;
  overflow: hidden;
}
.pw-plan {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 6px;
  padding: 4px 7px;
  border-radius: 6px;
