.pw-phone .pw-m-lambiase .pw-lambiase__team {
  display: block;
  font: 600 10px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #5A6894;
}
.pw-phone .pw-bars__bar {
  max-width: 24px;
}
.pw-landing {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  color: #EAF0FF;
  font: 400 13px/1.5 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  background: radial-gradient(800px 500px at 50% 0%, #12205A, #040920 70%);
}
.pw-landing__card {
  max-width: 460px;
  padding: 24px 28px;
  display: grid;
  gap: 10px;
  border-radius: 12px;
  border: 1px solid rgba(110, 150, 255, 0.32);
  background: rgba(8, 15, 44, 0.8);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.5), inset 0 2px 0 #E4002B;
}
.pw-landing__card .pw-brand__text {
  line-height: 1;
}
.pw-landing__card .pw-brand__text b {
  font: italic 900 26px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #fff;
  display: block;
}
.pw-landing__card .pw-brand__text span {
  font: 700 9px/1 'Titillium Web', 'Segoe UI', system-ui, -apple-system, sans-serif;
  letter-spacing: 0.22em;
  color: #FFC906;
}
.pw-landing__card p {
  margin: 0;
}
.pw-landing__card code {
  color: #FFC906;
}
.pw-landing__card .warn {
  color: #FF9F1C;
}
.pw-landing__card .dim {
  color: #8B9BC6;
}
.pw-loading {
  height: 3px;
  border-radius: 2px;
  background: rgba(110, 150, 255, 0.16);
  overflow: hidden;
}
.pw-loading i {
  display: block;
  width: 30%;
  height: 100%;
  background: linear-gradient(90deg, #E4002B, #FFC906);
  animation: pw-load 1.1s ease-in-out infinite;
}
@keyframes pw-load {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(340%);
  }
}
@media (max-width: 1280px) {
  .pw-tabs button {
    min-width: 0;
    padding: 4px 8px;
  }
  .pw-tabs button span {
    display: none;
  }
  .pw-tabs button em {
    display: none;
  }
  .pw-pick--wide select {
    min-width: 130px;
  }
}
@media (max-width: 980px) {
  .pw-brand {
    min-width: 0;
  }
  .pw-brand .pw-brand__text span {
    display: none;
  }
  .pw-titlerow h1 {
    font-size: 16px;
  }
  .pw-bottom__lambiase {
    display: none;
  }
}
